<script setup>
import { reactive,ref,computed,onMounted,onBeforeUnmount,watch } from 'vue'
import { viewNames,framingNames,basicSlots,selectReference } from './characterLibraryModel.js'
import CharacterScenePanel from './CharacterScenePanel.vue'
import { sceneSelectionChanged,sceneCompositionIssues } from './characterSceneModel.js'
const props=defineProps({api:Function}),emit=defineEmits(['navigate'])
const projects=ref([]),versions=ref([]),episodes=ref([]),shots=ref([]),projectId=ref(null),episodeId=ref(null),shotId=ref(null),cast=ref(null),state=ref(null),detail=ref(null),error=ref(''),busy=ref(false),resolved=ref(null),zoom=ref(null),human=ref(false),taskId=ref(null),reviewId=ref(null),planId=ref(null)
const roles=ref([{role:'主角',versionId:null}]),audio=ref('PostDubbing'),name=ref(''),note=ref(''),scope=ref('PreviewInspection')
const actors=ref([{role:'主角',view:'front',framing:'closeUp',position:'center',action:'',legacyHeadshotReferenceId:null}])
const shot=reactive({shotFraming:'closeUp',scene:'',action:'',camera:'Locked camera',props:'None',keyframeStartOnly:false})
const render=reactive({profile:'baseline480',seed:2026102701,repairOfTaskId:null,changeReason:'',promptAdjustment:''})
const sceneVersions=ref([]),sceneVersionId=ref(null),sceneBusy=ref(false),libraryReviews=ref([])
const selectedScene=computed(()=>sceneVersions.value.find(v=>v.id===sceneVersionId.value))
const compositionIssues=computed(()=>sceneVersionId.value&&!selectedScene.value?['所选场景版本不属于当前项目或已失效，不会回退另一版本。']:sceneCompositionIssues(selectedScene.value,shot,actors.value,cast.value?.episode?.payload.roles||[]))
const reviewFor=id=>libraryReviews.value.find(r=>r.versionId===id)
const versionLabel=v=>`${v.payload.characterName} · ${v.payload.label} · v${v.version} (#${v.id}) · ${reviewFor(v.id)?.contentStatus||'NeedReview'}`
const actorVersionIssues=computed(()=>[...new Set(actors.value.map(a=>cast.value?.episode?.payload.roles.find(r=>r.role===a.role)?.versionId).filter(id=>reviewFor(id)?.contentStatus==='Rejected'))].map(id=>`人物版本 #${id} 含被拒绝或失效的素材，当前调用已阻止；请保留待审或明确采用审核后的新版本。`))
const key=ref(crypto.randomUUID());const latest=computed(()=>state.value?.plans?.find(p=>p.id===planId.value)),selectedTask=computed(()=>state.value?.tasks?.find(t=>t.id===taskId.value)),latestReview=computed(()=>selectedTask.value?.review)
const readiness=ref(null),previewIds=ref(''),audioPath=ref(''),previewTask=ref(null),previewDetail=ref(null)
watch([render,planId,taskId,sceneVersionId,shot,actors],()=>{resolved.value=null;key.value=crypto.randomUUID()},{deep:true})
watch(()=>shot.shotFraming,value=>{for(const a of actors.value)a.framing=['fullBody','twoShot'].includes(value)?'fullBody':'closeUp'})
function actorVersion(a){const role=cast.value?.episode?.payload.roles.find(r=>r.role===a.role);return versions.value.find(v=>v.id===role?.versionId)}
function legacyPortraits(a){const v=actorVersion(a);return v?.payload.schema==='character-library-v1'?v.payload.references.filter(r=>r.view==='front'&&!r.framing):[]}
function recommended(a){const v=actorVersion(a);return a.legacyHeadshotReferenceId?v?.payload.references.find(r=>r.referenceId===a.legacyHeadshotReferenceId&&r.view==='front'):selectReference(v,a.view,a.framing)}
function actorForm(a){return {role:a.role,view:a.view,framing:a.framing,position:a.position,action:a.action,legacyHeadshotReferenceId:a.legacyHeadshotReferenceId??null}}
const legacyIssues=computed(()=>actors.value.some(a=>a.legacyHeadshotReferenceId&&(!legacyPortraits(a).some(r=>r.referenceId===a.legacyHeadshotReferenceId)||actors.value.length!==1||shot.shotFraming!=='closeUp'||a.view!=='front'||a.framing!=='closeUp'||sceneVersionId.value))?['旧版正面照片仅可明确用于单人面部近景；全身、多人或固定场景须选择对应完整参考。']:[])
const unsaved=computed(()=>latest.value&&(sceneSelectionChanged(latest.value,sceneVersionId.value)||['shotFraming','scene','action','camera','props'].some(k=>shot[k]!==latest.value.payload[k])||shot.keyframeStartOnly!==(latest.value.payload.keyframeStartOnly??false)||JSON.stringify(actors.value.map(actorForm))!==JSON.stringify(latest.value.payload.actors.map(actorForm))))
const selectedTaskPlanMismatch=computed(()=>selectedTask.value&&selectedTask.value.parameters?.storyPipeline?.planId!==planId.value)
const canVideo=computed(()=>!selectedTaskPlanMismatch.value&&detail.value?.task?.status==='Succeeded'&&detail.value.task.taskType==='Keyframe'&&latestReview.value?.payload.decision==='Passed')
const output=computed(()=>detail.value?.results?.find(r=>r.available&&r.assetPath?.endsWith(detail.value?.task?.taskType==='Keyframe'?'.png':'.mp4')))
const media=p=>'/api/media?assetPath='+encodeURIComponent(p),post=(path,body)=>props.api(path,{method:'POST',body:JSON.stringify(body)})
async function act(fn){if(busy.value||sceneBusy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function load(){[projects.value,versions.value,readiness.value,libraryReviews.value]=await Promise.all([props.api('/api/projects'),props.api('/api/character-library').then(r=>r.versions),props.api('/api/character-story/readiness'),props.api('/api/character-story/library-reviews')])}
async function loadScenes(){sceneVersions.value=projectId.value?await props.api('/api/character-story/scenes?projectId='+projectId.value):[]}
function applyPlan(p){for(const k of ['shotFraming','scene','action','camera','props','keyframeStartOnly'])shot[k]=p?.[k]??({shotFraming:'closeUp',scene:'',action:'',camera:'Locked camera',props:'None',keyframeStartOnly:false}[k]);sceneVersionId.value=p?.sceneBinding?.versionId??null;actors.value=p?p.actors.map(actorForm):[{role:cast.value?.episode?.payload.roles[0]?.role||'',view:'front',framing:'closeUp',position:'center',action:'',legacyHeadshotReferenceId:null}]}
function selectScene(){resolved.value=null;if(selectedScene.value){shot.scene=selectedScene.value.payload.sceneDescription;shot.camera=selectedScene.value.payload.camera}}
function clearTaskSelection(){taskId.value=null;detail.value=null;reviewId.value=null;resolved.value=null;human.value=false;note.value='';scope.value='PreviewInspection';Object.assign(render,{repairOfTaskId:null,changeReason:'',promptAdjustment:''})}
function clearShotSelection(){shotId.value=null;planId.value=null;state.value=null;sceneVersionId.value=null;clearTaskSelection();previewTask.value=null;previewDetail.value=null;previewIds.value='';audioPath.value=''}
async function selectProject(){episodeId.value=null;cast.value=null;sceneVersions.value=[];clearShotSelection();roles.value=[{role:'主角',versionId:null}];episodes.value=await props.api(`/api/projects/${projectId.value}/episodes`);await Promise.all([castState(),loadScenes()]);if(cast.value?.project){roles.value=cast.value.project.payload.roles.map(r=>({role:r.role,versionId:r.versionId}));audio.value=cast.value.project.payload.audioStrategy}}
async function castState(){if(projectId.value)cast.value=await props.api(`/api/character-story/projects/${projectId.value}/cast`+(episodeId.value?'?episodeId='+episodeId.value:''))}
async function selectEpisode(){clearShotSelection();shots.value=await props.api(`/api/episodes/${episodeId.value}/shots`);await castState()}
async function selectShot(){state.value=await props.api(`/api/character-story/shots/${shotId.value}`);planId.value=state.value.plans[0]?.id||null;clearTaskSelection();applyPlan(latest.value?.payload)}
async function selectTask(r){taskId.value=r.id;resolved.value=null;human.value=false;note.value='';scope.value='PreviewInspection';await refresh()}
function choosePlan(){clearTaskSelection();applyPlan(latest.value?.payload)}
async function refresh(){if(shotId.value)state.value=await props.api(`/api/character-story/shots/${shotId.value}`);if(taskId.value)detail.value=await props.api('/api/tasks/'+taskId.value);if(previewTask.value)previewDetail.value=await props.api('/api/tasks/'+previewTask.value);libraryReviews.value=await props.api('/api/character-story/library-reviews')}
async function preview(){await act(async()=>{const taskIds=previewIds.value.split(',').map(v=>Number(v.trim()));const r=await post('/api/character-story/preview',{episodeId:episodeId.value,taskIds,audioPath:audioPath.value||null,idempotencyKey:crypto.randomUUID()});previewTask.value=r.id;await refresh()})}
async function create(kind){await act(async()=>{if(!name.value.trim())throw new Error('填写项目、集或镜头名称');if(kind==='project'){const r=await post('/api/projects',{name:name.value,description:'人物选角与剧情关键帧送审预览',defaultWidth:864,defaultHeight:480,defaultFps:24});await load();projectId.value=r.id;await selectProject()}if(kind==='episode'){const r=await post('/api/episodes',{projectId:projectId.value,name:name.value,episodeNumber:episodes.value.length+1,outputWidth:864,outputHeight:480,outputFps:24});episodes.value=await props.api(`/api/projects/${projectId.value}/episodes`);episodeId.value=r.id;await selectEpisode()}if(kind==='shot'){const r=await post('/api/shots',{projectId:projectId.value,episodeId:episodeId.value,title:name.value,shotNumber:shots.value.length+1,width:864,height:480,frames:124,fps:24,durationSeconds:124/24});shots.value=await props.api(`/api/episodes/${episodeId.value}/shots`);shotId.value=r.id;await selectShot()}name.value=''})}
async function saveCast(){await act(async()=>{await post(`/api/character-story/projects/${projectId.value}/cast`,{roles:roles.value,audioStrategy:audio.value,idempotencyKey:crypto.randomUUID()});await castState()})}
async function snapshot(){await act(async()=>{await post(`/api/character-story/episodes/${episodeId.value}/cast`,{idempotencyKey:crypto.randomUUID()});await castState()})}
async function saveShot(){await act(async()=>{if(compositionIssues.value.length||actorVersionIssues.value.length||legacyIssues.value.length)throw Error([...compositionIssues.value,...actorVersionIssues.value,...legacyIssues.value].join('；'));const r=await post(`/api/character-story/shots/${shotId.value}`,{...shot,sceneVersionId:sceneVersionId.value,actors:actors.value,episodeCastId:cast.value.episode.id,idempotencyKey:crypto.randomUUID()});await refresh();planId.value=r.id;key.value=crypto.randomUUID();resolved.value=null})}
function request(){return {...render,planId:planId.value,keyframeTaskId:taskId.value||0,reviewId:latestReview.value?.id||reviewId.value||0,idempotencyKey:key.value}}
async function resolve(kind){await act(async()=>{resolved.value={...await post('/api/character-story/resolve/'+kind,request()),kind}})}
async function generate(){await act(async()=>{if(unsaved.value||compositionIssues.value.length||actorVersionIssues.value.length||legacyIssues.value.length)throw Error('先处理未冻结改动、场景绑定或人物审核问题');if(!resolved.value)throw new Error('先检查调用参数');const r=await post('/api/character-story/generate/'+resolved.value.kind,request());taskId.value=r.id;resolved.value=null;key.value=crypto.randomUUID();await refresh()})}
async function inspect(decision){await act(async()=>{if(scope.value==='HumanReview'&&!human.value)throw new Error('人工审核需操作员明确确认');await post('/api/character-story/inspect',{taskId:taskId.value,decision,scope:scope.value,humanConfirmed:human.value,note:note.value,idempotencyKey:crypto.randomUUID()});human.value=false;await refresh()})}
let timer;onMounted(()=>{act(load);timer=setInterval(()=>{if(!busy.value&&shotId.value)refresh().catch(e=>error.value=e.message)},7000)});onBeforeUnmount(()=>clearInterval(timer))
</script>
<template><section class="story-page">
  <el-alert title="剧情送审预览：从原有项目、Episode 和 Shot 选角，先检查剧情关键帧，再送入 H3 首帧路线。内容与正式发布仍待审核。" type="info" :closable="false"/>
  <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/>
  <el-alert v-if="readiness&&!readiness.ready" :title="readiness.message" type="warning" :closable="false" show-icon/>
  <section class="panel"><h2>项目选角与造型版本</h2><div class="controls"><el-select v-model="projectId" :disabled="busy||sceneBusy" aria-label="剧情项目" placeholder="选择项目" @change="()=>act(selectProject)"><el-option v-for="p in projects" :key="p.id" :value="p.id" :label="p.name"/></el-select><el-input v-model="name" aria-label="新项目集镜头名称" placeholder="新项目 / 集 / 镜头名称"/><el-button @click="create('project')" :disabled="busy">新建项目</el-button><el-button @click="emit('navigate','character-library')">查看人物参考库</el-button></div>
  <template v-if="projectId"><div class="controls" v-for="(r,i) in roles" :key="i"><el-input v-model="r.role" :aria-label="'剧情角色名 '+(i+1)" placeholder="剧情角色名"/><el-select v-model="r.versionId" :aria-label="'演员造型版本 '+(i+1)"><el-option v-for="v in versions" :key="v.id" :value="v.id" :label="versionLabel(v)" :disabled="reviewFor(v.id)?.contentStatus==='Rejected'"/></el-select><el-button @click="roles.splice(i,1)">移除此角色</el-button></div><div class="controls"><el-button @click="roles.push({role:'',versionId:null})">添加剧情角色</el-button><el-select v-model="audio" aria-label="音频策略"><el-option value="PostDubbing" label="后期配音（预览去除原生人声）"/><el-option value="ExistingDubbing" label="已有配音（合成时另选音轨）"/><el-option value="NativeH3" label="使用H3原生声音"/></el-select><el-button :disabled="busy" type="primary" @click="saveCast">保存项目选角</el-button></div><p v-if="cast?.project">选角快照 #{{cast.project.id}} · {{cast.project.sha256}}</p></template></section>
  <CharacterScenePanel v-if="projectId" :api="api" :project-id="projectId" :versions="sceneVersions" :disabled="busy" @busy-change="v=>sceneBusy=v" @refresh="()=>loadScenes().catch(e=>error=e.message)"/>
  <section v-if="projectId" class="panel"><h2>本集演员快照</h2><div class="controls"><el-select v-model="episodeId" :disabled="busy||sceneBusy" aria-label="剧情集" placeholder="选择现有集" @change="()=>act(selectEpisode)"><el-option v-for="e in episodes" :key="e.id" :value="e.id" :label="e.name"/></el-select><el-button :disabled="busy" @click="create('episode')">新建集</el-button><el-button :disabled="busy||!episodeId||!cast?.project" @click="snapshot">明确采用当前项目选角</el-button></div><el-alert v-if="cast?.projectChanged" title="项目选角已更新，本集继续保留原演员快照；需要时明确采用新快照。已有镜头不会自动替换。" type="warning" :closable="false"/><p v-if="cast?.episode">本集快照 #{{cast.episode.id}} · {{cast.episode.payload.roles.map(r=>r.role+' → '+r.name+' / #'+r.versionId).join('；')}}</p><p v-else>本集尚未固定演员；请先保存项目选角并明确采用。</p></section>
  <section v-if="episodeId" class="panel"><h2>分镜人物、方向与动作</h2><div class="controls"><el-select v-model="shotId" :disabled="busy||sceneBusy" aria-label="剧情镜头" @change="()=>act(selectShot)"><el-option v-for="s in shots" :key="s.id" :value="s.id" :label="s.shotNumber+' · '+s.title"/></el-select><el-button :disabled="busy" @click="create('shot')">新建镜头</el-button></div>
  <template v-if="shotId&&cast?.episode"><el-alert v-for="issue in legacyIssues" :key="issue" :title="issue" type="error" :closable="false" show-icon/><el-alert v-for="issue in actorVersionIssues" :key="issue" :title="issue" type="error" :closable="false" show-icon/><div class="controls"><el-select v-model="sceneVersionId" clearable aria-label="镜头场景版本" placeholder="原有文字场景路线" :disabled="busy||sceneBusy" @change="selectScene"><el-option v-for="v in sceneVersions" :key="v.id" :value="v.id" :label="`${v.payload.sceneName} · v${v.version} (#${v.id})`"/></el-select><span v-if="sceneVersionId">场景 #{{sceneVersionId}} · 明确绑定，不自动追随新版本</span><span v-else>原有文字场景路线；未绑定固定背景</span></div><p v-if="selectedScene">基准演员与站位：{{selectedScene.payload.actorVersions.map(a=>'人物 #'+a.characterId+' / 造型版本 #'+a.versionId+' / '+(a.position==='left'?'画面左':'画面右')).join('；')}}。选择版本沿用场景与机位描述，演员须自行核对。</p><el-alert v-for="issue in compositionIssues" :key="issue" :title="issue" type="warning" :closable="false"/><div class="controls"><el-select v-model="shot.shotFraming" aria-label="剧情景别"><el-option value="closeUp" label="面部近景"/><el-option value="medium" label="半身"/><el-option value="fullBody" label="全身"/><el-option value="twoShot" label="双人同框"/></el-select><el-button :disabled="actors.length>=2" @click="actors.push({role:'',view:'front',framing:'fullBody',position:'right',action:''})">添加第二人物（独立身份与服装）</el-button></div>
  <div class="actor" v-for="(a,i) in actors" :key="i"><strong>人物 {{i+1}}</strong><div class="controls"><el-select v-model="a.role" :aria-label="'镜头角色 '+(i+1)" @change="a.legacyHeadshotReferenceId=null"><el-option v-for="r in cast.episode.payload.roles" :key="r.role" :value="r.role" :label="r.role+' → '+r.name"/></el-select><el-select :model-value="a.view+':'+a.framing" :aria-label="'推荐参考 '+(i+1)" @update:model-value="v=>{[a.view,a.framing]=v.split(':');a.legacyHeadshotReferenceId=null}"><el-option v-for="[v,f] in basicSlots" :key="v+f" :value="v+':'+f" :label="viewNames[v]+' · '+framingNames[f]"/></el-select><el-select v-if="legacyPortraits(a).length&&shot.shotFraming==='closeUp'&&actors.length===1" v-model="a.legacyHeadshotReferenceId" clearable :aria-label="'明确选择旧版正面近照 '+(i+1)" placeholder="明确选择已审旧版正面参考"><el-option v-for="r in legacyPortraits(a)" :key="r.referenceId" :value="r.referenceId" :label="'旧版正面参考 #'+r.referenceId"/></el-select><el-select v-model="a.position" :aria-label="'人物站位 '+(i+1)"><el-option value="left" label="画面左"/><el-option value="center" label="画面中"/><el-option value="right" label="画面右"/></el-select><el-input v-model="a.action" :aria-label="'人物动作 '+(i+1)" placeholder="该人物动作及关系"/><el-button v-if="actors.length>1" @click="actors.splice(i,1)">移除</el-button></div></div>
  <p v-if="actors.some(a=>legacyPortraits(a).length) && shot.shotFraming==='closeUp'">旧版正面近照须明确选择，提交时重新核验素材已审核通过；此模式仅供单人面部近景，不补充或声明全身参考。</p>
  <div class="bound-refs"><div v-for="a in actors" :key="a.role"><strong>{{a.role}} · 推荐{{viewNames[a.view]}} {{framingNames[a.framing]}}</strong><img v-if="recommended(a)" :src="media(recommended(a).assetPath)" :alt="a.role+' 推荐参考'" @click="zoom=recommended(a).assetPath"/><el-alert v-else title="选定版本缺少对应参考，不会自动替换另一张图片" type="error" :closable="false"/></div></div>
  <el-checkbox v-model="shot.keyframeStartOnly">关键帧只呈现人物起始状态</el-checkbox><p>勾选后，关键帧使用上方各人物的起始状态；完整剧情动作留给视频。历史计划保持原样。</p>
  <el-form label-position="top"><el-form-item label="剧情场景"><el-input v-model="shot.scene" aria-label="剧情场景"/></el-form-item><el-form-item label="动作与起始状态"><el-input v-model="shot.action" aria-label="剧情动作"/></el-form-item><el-form-item label="机位与镜头"><el-input v-model="shot.camera" aria-label="剧情机位"/></el-form-item><el-form-item label="必要道具与人物关系"><el-input v-model="shot.props" aria-label="剧情道具"/></el-form-item></el-form><el-button type="primary" :disabled="busy||sceneBusy||compositionIssues.length>0||actorVersionIssues.length>0||legacyIssues.length>0" @click="saveShot">冻结此镜头的人物与参考</el-button></template>
  <div v-if="state?.plans?.length" class="controls"><el-select v-model="planId" :disabled="busy" aria-label="镜头计划版本" @change="choosePlan"><el-option v-for="p in state.plans" :key="p.id" :value="p.id" :label="'计划 #'+p.id+' · v'+p.version"/></el-select><el-button @click="()=>act(refresh)">刷新任务</el-button></div>
  <div v-if="latest" class="bound-refs"><div v-for="a in latest.payload.actors" :key="a.role"><strong>{{a.role}} / 人物版本 #{{a.versionId}}</strong><img :src="media(a.reference.assetPath)" :alt="a.role+' 已绑定参考'" @click="zoom=a.reference.assetPath"/><small>{{a.reference.sha256}}</small></div></div>
  </section>
  <section v-if="planId" class="panel"><h2>剧情关键帧 → 检查 → H3试片</h2><p>普通人物库照片仅供身份与造型参考。多人使用四个独立人物输入制作静态候选，绑定场景时增加第五个构图输入；实际身份绑定效果必须逐张检查，未通过不能生成视频。H3可接收已检查的剧情关键帧；同场景接续也可使用上一镜已检查视频的实际尾帧，目前由受控本地流程提交并在此显示任务。Ref2VA未启用。</p><el-alert v-if="unsaved" title="当前分镜改动尚未冻结；请先保存镜头计划，再生成对应关键帧。历史计划与任务保持原绑定。" type="warning" :closable="false"/><div class="controls"><el-input-number v-model="render.seed" :min="0" :max="9007199254740991" aria-label="剧情种子"/><el-select v-model="render.profile" aria-label="H3画质规格"><el-option value="baseline480" label="已验证 864×480 · 24fps · 124帧"/><el-option value="quality768" label="已验证 1376×768 · 24fps · 124帧"/><el-option value="native1080" label="原生 1920×1088 · 24fps · 124帧"/></el-select><el-button :disabled="busy||sceneBusy||unsaved||compositionIssues.length>0||actorVersionIssues.length>0||legacyIssues.length>0" @click="resolve('Keyframe')">检查关键帧调用</el-button><el-button :disabled="busy||sceneBusy||!canVideo||unsaved||compositionIssues.length>0||actorVersionIssues.length>0||legacyIssues.length>0" @click="resolve('Video')">检查H3首帧调用</el-button></div>
  <div class="controls"><el-input-number v-model="render.repairOfTaskId" :min="1" aria-label="原失败剧情任务"/><el-input v-model="render.changeReason" aria-label="剧情修复原因" placeholder="定向修复原因与改变；仅失败项，最多两次"/><el-input v-model="render.promptAdjustment" type="textarea" aria-label="剧情定向提示词" placeholder="只修失败内容的提示词，例如：双手分开、保持各自站位"/></div><details v-if="resolved" open><summary>提交前核对：{{resolved.kind}} · ReviewPreview</summary><pre>{{resolved.task}}</pre><el-button :disabled="busy||sceneBusy||unsaved||compositionIssues.length>0||actorVersionIssues.length>0||legacyIssues.length>0" type="primary" @click="generate">提交已检查的队列任务</el-button></details>
  <el-table :data="state?.tasks||[]" size="small" @row-click="r=>act(()=>selectTask(r))"><el-table-column prop="id" label="任务ID" width="85"/><el-table-column prop="taskType" label="阶段" width="120"/><el-table-column prop="status" label="状态" width="120"/><el-table-column label="检查状态" width="180"><template #default="{row}">{{row.review?.payload.decision||'NeedReview'}} / {{row.review?.payload.scope||'待检查'}}</template></el-table-column><el-table-column label="失败原因 / 检查说明"><template #default="{row}">{{row.error||row.review?.payload.note||"待检查"}}</template></el-table-column></el-table>
  <el-alert v-if="selectedTaskPlanMismatch" title="所选任务属于另一镜头计划版本；请切换到对应计划后调用，不会自动改绑。" type="warning" :closable="false"/><template v-if="detail"><p>选中任务 #{{taskId}} · {{detail.task.status}} · 内容待审 · 发布 Blocked</p><el-alert v-if="latestReview" :title="latestReview.payload.decision+' / '+latestReview.payload.scope+'：'+latestReview.payload.note" :type="latestReview.payload.decision==='Failed'?'error':'info'" :closable="false"/><details v-if="selectedTask?.parameters"><summary>查看来源、生成参数与任务依赖</summary><pre>{{selectedTask.parameters}}</pre></details><img v-if="output?.assetPath.endsWith('.png')" class="keyframe" :src="media(output.assetPath)" alt="剧情关键帧原图" @click="zoom=output.assetPath"/><video v-else-if="output" class="keyframe" :src="media(output.assetPath)" :muted="latest?.payload.audioStrategy!=='NativeH3'" controls preload="metadata"/><div v-if="output" class="controls"><el-select v-model="scope" aria-label="检查性质"><el-option value="PreviewInspection" label="试片检查（内容仍待人工最终审核）"/><el-option value="HumanReview" label="人工内容审核"/></el-select><el-checkbox v-if="scope==='HumanReview'" v-model="human">由人工查看原图/视频</el-checkbox><el-input v-model="note" type="textarea" aria-label="剧情具体检查说明" placeholder="脸、衣服、身体、手部、道具与站位的具体检查结论"/><el-button :disabled="busy||(scope==='HumanReview'&&!human)" @click="inspect('Passed')">记录检查通过</el-button><el-button :disabled="busy||(scope==='HumanReview'&&!human)" type="danger" plain @click="inspect('Failed')">记录内容失败</el-button></div></template>
  </section><section v-if="episodeId" class="panel"><h2>本集合成送审预览</h2><p>按镜头顺序填写已检查视频任务ID。后期配音策略输出静音预览；原生声音保留原轨；已有配音须选择受控音轨，移除原生人声后再混音。</p><div class="controls"><el-input v-model="previewIds" aria-label="预览视频任务顺序" placeholder="视频任务ID，英文逗号分隔"/><el-input v-model="audioPath" aria-label="已有配音文件" placeholder="已有配音的受控媒体路径（按策略填写）"/><el-button :disabled="busy||!previewIds" @click="preview">提交CPU合成预览</el-button></div><p v-if="previewDetail">预览任务 #{{previewTask}} · {{previewDetail.task.status}} · 内容待审 / 发布 Blocked</p><video v-for="r in (previewDetail?.results||[]).filter(r=>r.available&&r.assetPath?.endsWith('.mp4'))" :key="r.id" class="keyframe" :src="media(r.assetPath)" controls preload="metadata"/></section><el-dialog :model-value="!!zoom" title="剧情原图检查" width="96%" @update:model-value="v=>{if(!v)zoom=null}"><img v-if="zoom" class="keyframe" :src="media(zoom)" alt="剧情原图放大"/></el-dialog>
</section></template>
<style scoped>.story-page{display:grid;gap:18px}.panel{padding:20px;min-width:0}.controls{display:flex;flex-wrap:wrap;gap:10px;margin:14px 0}.controls .el-select,.controls .el-input{width:300px}.actor{border-top:1px solid #8290aa;padding:10px 0}.bound-refs{display:flex;gap:20px;flex-wrap:wrap}.bound-refs>div{max-width:340px;display:grid;gap:8px}.bound-refs img{width:100%;cursor:zoom-in}.bound-refs small{overflow-wrap:anywhere}.keyframe{width:100%;max-height:75vh;object-fit:contain;cursor:zoom-in}pre{max-height:430px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere}</style>
